 * - `inlineData` parts become `{ type: 'media' }` preserving `data`/`mimeType`.
 * - `fileData` parts become `{ type: 'media' }` mapping `fileUri` -> `uri`.
 * - `functionCall`/`functionResponse` parts are skipped.
 * - Anything else is serialized to a `text` part flagged as unknown via `_meta`.
 */
export function geminiPartsToContentParts(parts: Part[]): ContentPart[] {
  const result: ContentPart[] = [];

  for (const part of parts) {
    if (part.thought) {
      const thoughtPart: ContentPart = {
        type: 'thought',
        thought: part.text ?? '',
      };
      if (part.thoughtSignature !== undefined) {
        thoughtPart.thoughtSignature = part.thoughtSignature;
      }
      result.push(thoughtPart);
    } else if (part.text !== undefined) {
      result.push({ type: 'text', text: part.text });
    } else if (part.inlineData) {
      result.push({
        type: 'media',
        data: part.inlineData.data,
        mimeType: part.inlineData.mimeType,
      });
    } else if (part.fileData) {
      result.push({
        type: 'media',
        uri: part.fileData.fileUri,
        mimeType: part.fileData.mimeType,
      });
    } else if (part.functionCall || part.functionResponse) {
      // Function calls and responses are handled elsewhere; skip them here.
      continue;
    } else {
      result.push({
        type: 'text',
        text: JSON.stringify(part),
        _meta: { unknown: true },
      });
    }
  }

  return result;
}

/**
