 * objects.
 *
 * - `text` parts become `{ text }`.
 * - `thought` parts become `{ text, thought: true, thoughtSignature? }`.
 * - `media` parts with `data` become `inlineData` parts (defaulting `mimeType`
 *   to `application/octet-stream`).
 * - `media` parts with `uri` become `fileData` parts.
 * - `media` parts with neither `data` nor `uri` are skipped.
 * - Anything else is serialized to a `{ text }` part.
 */
export function contentPartsToGeminiParts(parts: ContentPart[]): Part[] {
  const result: Part[] = [];

  for (const part of parts) {
    switch (part.type) {
      case 'text': {
        result.push({ text: part.text });
        break;
      }
      case 'thought': {
        const thoughtPart: Part = { text: part.thought, thought: true };
        if (part.thoughtSignature !== undefined) {
          thoughtPart.thoughtSignature = part.thoughtSignature;
        }
        result.push(thoughtPart);
        break;
      }
      case 'media': {
        if (part.data !== undefined) {
          result.push({
            inlineData: {
              data: part.data,
              mimeType: part.mimeType ?? 'application/octet-stream',
            },
          });
        } else if (part.uri !== undefined) {
          result.push({
            fileData: {
              fileUri: part.uri,
              mimeType: part.mimeType,
            },
          });
        }
        // Media with neither data nor uri is skipped.
        break;
      }
      default: {
        result.push({ text: JSON.stringify(part) });
        break;
      }
    }
  }

  return result;
}

/**
